H.background();
const m = P.m;
const dT = P.dT;
const c = 4.18;
const q = m * c * dT;
const v = H.plot2d({ xMin: 0, xMax: 60, yMin: 0, yMax: 100 });
v.grid(); v.axes();
const Ti = 20;
const heating = dT >= 0;
const tau = 18;
const Tfinal = Ti + dT;
const Tof = tt => Ti + dT * (1 - Math.exp(-tt / tau));
v.fn(x => Tof(x), { color: heating ? H.colors.warn : H.colors.accent, width: 3 });
v.line(0, Ti, 60, Ti, { color: H.colors.grid, width: 1.5, dash: [5, 4] });
v.line(0, Tfinal, 60, Tfinal, { color: H.colors.sub, width: 1.5, dash: [5, 4] });
const tt = (t * 6) % 60;
v.dot(tt, Tof(tt), { r: 7, fill: H.colors.accent2 });
H.text("Calorimetry:  q = m c dT", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Water, c = 4.18 J/(g K).  q>0 absorbs heat, q<0 releases heat", 24, 52, { color: H.colors.sub, size: 13 });
H.text("m = " + m.toFixed(0) + " g,  dT = " + dT.toFixed(0) + " K,  c = 4.18 J/(g K)", 24, 80, { color: H.colors.sub, size: 13 });
H.text("q = " + q.toFixed(0) + " J  = " + (q / 1000).toFixed(2) + " kJ" + (heating ? "  (absorbed)" : "  (released)"), 24, 102, { color: H.colors.accent2, size: 14, weight: 700 });
